+const (
+	maxEncodedShapes       = 10000000
+	maxEncodedCells        = 10000000
+	maxEncodedEdgesPerCell = 10000000
+)
+
+// Encode encodes the ShapeIndex to the given io.Writer.
+// All pending updates are applied before encoding so that the full spatial
+// cell structure is serialized.
+func (s *ShapeIndex) Encode(w io.Writer) error {
+	if s == nil {
+		return fmt.Errorf("s2: nil ShapeIndex")
+	}
+	if w == nil {
+		return fmt.Errorf("s2: nil writer")
+	}
+	s.maybeApplyUpdates()
+
+	e := &encoder{w: w}
+	s.encode(e)
+	return e.err
+}
+
+func (s *ShapeIndex) encode(e *encoder) {
+	e.writeInt8(encodingVersion)
+	e.writeInt32(int32(s.maxEdgesPerCell))
+	e.writeInt32(s.nextID)
+
+	// Encode shapes in deterministic sorted order of shapeID.
+	shapeIDs := make([]int32, 0, len(s.shapes))
+	for id := range s.shapes {
+		shapeIDs = append(shapeIDs, id)
+	}
+	slices.Sort(shapeIDs)
+
+	e.writeUint32(uint32(len(shapeIDs)))
+	for _, id := range shapeIDs {
+		shape := s.shapes[id]
+		tag := shape.typeTag()
+		switch tag {
+		case typeTagPolygon, typeTagPolyline, typeTagPointVector, typeTagLaxPolyline,
+			typeTagLaxPolygon, typeTagLoop, typeTagLaxLoop:
+			// supported
+		default:
+			e.err = fmt.Errorf("shape with ID %d has unsupported type tag %d", id, tag)
+			return
+		}
+
+		e.writeInt32(id)
+		e.writeUint32(uint32(tag))
+
+		switch sh := shape.(type) {
+		case *Polygon:
+			sh.encode(e)
+		case *Polyline:
+			sh.encode(e)
+		case *PointVector:
+			sh.encode(e)
+		case *LaxPolyline:
+			sh.encode(e)
+		case *LaxPolygon:
+			sh.encode(e)
+		case *Loop:
+			sh.encode(e)
+		case *LaxLoop:
+			sh.encode(e)
+		default:
+			e.err = fmt.Errorf("shape with ID %d has unexpected concrete type %T", id, shape)
+			return
+		}
+		if e.err != nil {
+			return
+		}
+	}
+
+	// Encode spatial cells.
+	e.writeUint32(uint32(len(s.cells)))
+	for _, cellID := range s.cells {
+		cell := s.cellMap[cellID]
+		numCShapes := 0
+		if cell != nil {
+			numCShapes = len(cell.shapes)
+		}
+
+		e.writeUint64(uint64(cellID))
+		e.writeUint32(uint32(numCShapes))
+
+		for i := 0; i < numCShapes; i++ {
+			cs := cell.shapes[i]
+			e.writeInt32(cs.shapeID)
+			e.writeBool(cs.containsCenter)
+			e.writeUint32(uint32(len(cs.edges)))
+			for _, edgeID := range cs.edges {
+				e.writeInt32(int32(edgeID))
+			}
+			if e.err != nil {
+				return
+			}
+		}
+	}
+}
+
+// Decode decodes the ShapeIndex from the given io.Reader.
+// The decoded index has its spatial cell structure intact and is ready for queries
+// and iteration without requiring Build.
+func (s *ShapeIndex) Decode(r io.Reader) error {
+	if s == nil {
+		return fmt.Errorf("s2: nil ShapeIndex")
+	}
+	if r == nil {
+		return fmt.Errorf("s2: nil reader")
+	}
+	s.Reset()
+	d := &decoder{r: asByteReader(r)}
+	s.decode(d)
+	return d.err
+}
+
+func (s *ShapeIndex) decode(d *decoder) {
+	version := d.readInt8()
+	if d.err != nil {
+		return
+	}
+	if version != encodingVersion {
+		d.err = fmt.Errorf("can't decode version %d; my version: %d", version, encodingVersion)
+		return
+	}
+
+	maxEdgesPerCell := d.readInt32()
+	nextID := d.readInt32()
+	if d.err != nil {
+		return
+	}
+	if maxEdgesPerCell <= 0 {
+		d.err = fmt.Errorf("invalid maxEdgesPerCell: %d", maxEdgesPerCell)
+		return
